def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    A = list(map(int, data[1:1 + n]))
    MOD = 998244353

    maxn = 2 * n + 10
    fact = [1] * maxn
    for i in range(1, maxn):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * maxn
    inv_fact[maxn - 1] = pow(fact[maxn - 1], MOD - 2, MOD)
    for i in range(maxn - 1, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a, b):
        if b < 0 or a < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    # T(r, K) = sum_{k=1}^{K} B(r,k), where B(r,k) = number of ordered forests
    # of k plane trees with r nodes total = C(2r-k-1, r-1) - C(2r-k-1, r).
    # Hockey stick over the two binomial families gives a closed form.
    def T(r, K):
        if K <= 0:
            return 0
        if K > r:
            K = r
        m = 2 * r - K - 1
        return (comb(2 * r - 1, r) - comb(m, r) - comb(2 * r - 1, r + 1) + comb(m, r + 1)) % MOD

    ans = 0
    S = 0  # S_{i-1}
    for i in range(1, n + 1):
        a = A[i - 1]
        r = n - i
        if r == 0:
            if S == 0 and a >= 1:
                ans += 1
        else:
            klo = S if S > 1 else 1
            khi = S + a - 1
            if khi > r:
                khi = r
            if khi >= klo:
                ans = (ans + T(r, khi) - T(r, klo - 1)) % MOD
        S += a - 1
        if S < 0:
            if i == n and S == -1:
                ans += 1
            break

    sys.stdout.write(str(ans % MOD) + "\n")


