class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # OFFLINE events are processed before MESSAGE events at the same timestamp.
        order = sorted(
            range(len(events)),
            key=lambda i: (int(events[i][1]), 0 if events[i][0] == "OFFLINE" else 1, i),
        )

        mentions = [0] * numberOfUsers
        # offline_until[u] = time at which user u is online again (<= t means online)
        offline_until = [0] * numberOfUsers

        for idx in order:
            ev = events[idx]
            kind = ev[0]
            t = int(ev[1])
            if kind == "OFFLINE":
                uid = int(ev[2])
                offline_until[uid] = t + 60
            else:
                tokens = ev[2].split()
                for tok in tokens:
                    if tok == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif tok == "HERE":
                        for u in range(numberOfUsers):
                            if offline_until[u] <= t:
                                mentions[u] += 1
                    elif tok.startswith("id"):
                        uid = int(tok[2:])
                        if 0 <= uid < numberOfUsers:
                            mentions[uid] += 1

        return mentions

