    # dp[a][b] = bitmask of achievable "free cell" counts using at most a rows
    # and at most b columns, where each strongly connected block (r, c) with
    # r >= 2, c >= 2 contributes r*c free cells.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        row = dp[a]
        for b in range(n + 1):
            v = 1  # sum 0 is always achievable
            if a:
                v |= dp[a - 1][b]
            if b:
                v |= row[b - 1]
            for r in range(2, a + 1):
                prev = dp[a - r]
                for c in range(2, b + 1):
                    sub = prev[b - c]
                    if sub:
                        v |= sub << (r * c)
            row[b] = v

    reach = dp[n][n]
    out = []
    for i in range(q):
        k = int(data[2 + i])
        m = total - k
        if 0 <= m <= total and (reach >> m) & 1:
            out.append("Yes")
        else:
            out.append("No")
