class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float],
                  pairs2: List[List[str]], rates2: List[float]) -> float:
        def best_amounts(pairs, rates, start):
            # Build bidirectional edges: a -> b at rate r, b -> a at rate 1/r
            edges = []
            nodes = {start}
            for (a, b), r in zip(pairs, rates):
                r = float(r)
                edges.append((a, b, r))
                edges.append((b, a, 1.0 / r))
                nodes.add(a)
                nodes.add(b)

            amt = {start: 1.0}
            # Bellman-Ford style relaxation for maximum product
            for _ in range(len(nodes) + 1):
                changed = False
                for a, b, r in edges:
                    if a in amt:
                        cand = amt[a] * r
                        if cand > amt.get(b, 0.0) * (1 + 1e-15):
                            amt[b] = cand
                            changed = True
                if not changed:
                    break
            return amt

        day1 = best_amounts(pairs1, rates1, initialCurrency)
        day2 = best_amounts(pairs2, rates2, initialCurrency)

        ans = 1.0
        for cur, val in day1.items():
            if cur in day2:
                # day2[cur] = best amount of `cur` per 1 initialCurrency on day 2,
                # so converting `cur` back to initialCurrency yields 1 / day2[cur]
                ans = max(ans, val / day2[cur])
        return ans

