class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        NEG = -(10 ** 18)
        HALF = NEG // 2

        # dp[j][k] = best profit reaching cell (i-1, j) using at most k neutralizations
        dp = [[NEG] * 3 for _ in range(n)]

        for i in range(m):
            ndp = [[NEG] * 3 for _ in range(n)]
            for j in range(n):
                c = coins[i][j]

                if i == 0 and j == 0:
                    base = [0, NEG, NEG]
                else:
                    base = [NEG, NEG, NEG]
                    for k in range(3):
                        v = NEG
                        if i > 0:
                            up = dp[j][k]
                            if up > v:
                                v = up
                        if j > 0:
                            left = ndp[j - 1][k]
                            if left > v:
                                v = left
                        base[k] = v

                for k in range(3):
                    val = NEG
                    if base[k] > HALF:
                        val = base[k] + c
                    if k >= 1 and base[k - 1] > HALF and base[k - 1] > val:
                        # neutralize the robber (or simply skip the value) in this cell
                        val = base[k - 1]
                    ndp[j][k] = val

                # "at most k" must be monotone non-decreasing in k
                if ndp[j][1] < ndp[j][0]:
                    ndp[j][1] = ndp[j][0]
                if ndp[j][2] < ndp[j][1]:
                    ndp[j][2] = ndp[j][1]

            dp = ndp

        return dp[n - 1][2]


