class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)

        # Baseline: adjacent pairs where both values are known.
        base = 0
        for i in range(n - 1):
            a, b = nums[i], nums[i + 1]
            if a != -1 and b != -1:
                dif = a - b
                if dif < 0:
                    dif = -dif
                if dif > base:
                    base = dif

        # Collect maximal runs of -1 together with their known neighbours.
        segs = []  # (length, neighbours)
        i = 0
        while i < n:
            if nums[i] == -1:
                j = i
                while j < n and nums[j] == -1:
                    j += 1
                nb = []
                if i > 0:
                    nb.append(nums[i - 1])
                if j < n:
                    nb.append(nums[j])
                segs.append((j - i, nb))
                i = j
            else:
                i += 1

        if not segs:
            return base

        INF = float('inf')

        def pierce2(intervals, maxdist):
            # Can two points (optionally at distance <= maxdist) stab every interval?
            for l, r in intervals:
                if l > r:
                    return False
            if not intervals:
                return True
            R = INF
            for l, r in intervals:
                if r < R:
                    R = r
            L2 = -INF
            R2 = INF
            any_left = False
            for l, r in intervals:
                if l > R or r < R:
                    any_left = True
                    if l > L2:
                        L2 = l
                    if r < R2:
                        R2 = r
            if not any_left:
                return True
            if L2 > R2:
                return False
            if maxdist is not None and (L2 - R) > maxdist:
                return False
            return True

        def feasible(d):
            if d < base:
                return False
            iv2 = []  # |x - y| > d  : every gap must be bridged by a single value
            iv1 = []  # |x - y| <= d : long gaps may use both values
            for ln, nb in segs:
                k = len(nb)
                if k == 0:
                    continue
                if k == 1:
                    a = nb[0]
                    lo = a - d
                    hi = a + d
                    if lo < 1:
                        lo = 1
                    iv2.append((lo, hi))
                    iv1.append((lo, hi))
                else:
                    a, b = nb
                    if a > b:
                        hi_v, lo_v = a, b
                    else:
                        hi_v, lo_v = b, a
                    lo = hi_v - d
                    hi = lo_v + d
                    if lo < 1:
                        lo = 1
                    iv2.append((lo, hi))
                    if ln == 1:
                        iv1.append((lo, hi))
                    else:
                        la = a - d
                        if la < 1:
                            la = 1
                        lb = b - d
                        if lb < 1:
                            lb = 1
                        iv1.append((la, a + d))
                        iv1.append((lb, b + d))
            if pierce2(iv2, None):
                return True
            return pierce2(iv1, d)

        lo, hi = base, 10 ** 9
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def canAliceWin(self, n: int) -> bool:
        remove = 10
        turn = 0  # 0 = Alice's turn, 1 = Bob's turn
        while remove > 0 and n >= remove:
            n -= remove
            remove -= 1
            turn ^= 1
        # The player whose turn it is now cannot move, so they lose.
        return turn == 1

