def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    M = int(data[1])
    Pl = list(map(int, data[2:2 + n]))
    Pmin = min(Pl)

    # Marginal cost of the k-th unit of product i is P_i * (2k - 1).
    # Greedily take every marginal cost <= X.  For threshold X:
    #   k_i(X) = floor((floor(X / P_i) + 1) / 2)
    # cost(X) = sum P_i * k_i^2 , count(X) = sum k_i  (both non-decreasing in X)
    # Binary search the largest feasible X, then spend the leftover budget on
    # units whose marginal cost is exactly X+1.

    # Upper bound guaranteed to be infeasible:
    #   k_min >= X/(2*Pmin) - 1/2 > sqrt(M/Pmin)  ==>  Pmin*k^2 > M
    Hi = 2 * isqrt(M * Pmin) + Pmin + 3

    try:
        import numpy as np
    except Exception:
        np = None

    if np is not None:
        P = np.array(Pl, dtype=np.int64)
        # Cap on k beyond which P*k^2 is certainly > M (avoids int64 overflow).
        Kcap = np.floor(np.sqrt((M // P).astype(np.float64))).astype(np.int64) + 3
        Pf = P.astype(np.float64)

        def cost_count(X):
            k = (X // P + 1) // 2
            if bool(np.any(k > Kcap)):
                return None
            kf = k.astype(np.float64)
            approx = float(np.dot(Pf * kf, kf))
            if approx > 1.9 * M:
                return None
            c = int(np.sum(P * k * k))
            if c > M:
                return None
            return (c, int(np.sum(k)))

        def count_only(X):
            k = (X // P + 1) // 2
            return int(np.sum(k))
    else:
        def cost_count(X):
            tot = 0
            cnt = 0
            for p in Pl:
                k = ((X // p) + 1) >> 1
                if k:
                    tot += p * k * k
                    if tot > M:
                        return None
                    cnt += k
            return (tot, cnt)

        def count_only(X):
            s = 0
            for p in Pl:
                s += ((X // p) + 1) >> 1
            return s

    lo = 0
    hi = Hi
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if cost_count(mid) is not None:
            lo = mid
        else:
            hi = mid - 1

    X = lo
    res = cost_count(X)
    cost, cnt = res
    rem = M - cost
    avail = count_only(X + 1) - cnt
    step = X + 1
    add = rem // step
    if add > avail:
        add = avail
    if add < 0:
        add = 0
    sys.stdout.write(str(cnt + add) + "\n")


main()

from typing import List


class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)
        for l, r in queries:
            diff[l] += 1
            diff[r + 1] -= 1
        cur = 0
        for i in range(n):
            cur += diff[i]
            if cur < nums[i]:
                return False
        return True
